const counts = { general:0, technology:0, ai:0, math:0, physics:0 };
function getChapterId(world, n) {
  const ch1Targets = { general:18, technology:20, ai:18, math:16, physics:18 };
  const target1 = ch1Targets[world] || 18;
  if (n <= target1) return 1;
  const rem = n - target1;
  const remChapters = 9;
  const remQuestions = 80 - target1;
  const perCh = remQuestions / remChapters;
  const chOffset = Math.min(8, Math.floor((rem - 1) / perCh));
  return 2 + chOffset;
}
function addGroup(world, topicId, subtopic, sourceKey, rows) {
  return rows.map(([q, correctText, why, difficulty, wrong, rowSourceKey]) => {
    const n = ++counts[world];
    const chapterId = getChapterId(world, n);
    const key = rowSourceKey || sourceKey;
    const sourceTemplate = SOURCES[key];
    if (!sourceTemplate) throw new Error('Unknown source key: ' + key);
    const source = {
      title:sourceTemplate.title,
      url:sourceTemplate.url,
      claim:why,
      status:sourceTemplate.status,
      ...(sourceTemplate.status === 'verified' ? { lastVerified:CHECKED } : {}),
    };
    const record = {
      id:`${world}-extra-${String(n + 20).padStart(3,'0')}`,
      q, correctText, why, difficulty, topicId, subtopic, chapterId,
      answerFamily:`${topicId} concepts`,
      distractors:wrong.map(text => ({
        text,
        rationale:`${text} is a related but incorrect choice; the cited fact specifies ${correctText}.`,
      })),
      source,
    };
    if (sourceTemplate.status === 'verified') record.verifiedAt = CHECKED;
    return record;
  });
}

